function applyTheme(theme){
 document.documentElement.dataset.theme=theme;
 document.querySelectorAll('[data-theme-choice]').forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.themeChoice===theme)));
 document.querySelector('meta[name="theme-color"]').content=theme==='dark'?'#0d1c24':'#f5f7f4';
 try{localStorage.setItem('atlas-theme',theme)}catch(e){}
}
document.querySelectorAll('[data-theme-choice]').forEach(button=>button.addEventListener('click',()=>applyTheme(button.dataset.themeChoice)));
applyTheme(document.documentElement.dataset.theme==='dark'?'dark':'light');
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>n===null?'Unknown':`${new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(n)} MW`;
const statusLabel=s=>s==='Under construction'?'Building':s==='Proposed / planned'?'Planned':'Operating';
const statusClass=s=>s==='Under construction'?'building':s==='Proposed / planned'?'planned':'operating';
const place=r=>`${r.city}, ${r.region}, ${r.country==='USA'?'U.S.':r.country}`;
const countries=[['USA','United States'],['Canada','Canada'],['Mexico','Mexico']];
const stages=['Operational','Under construction','Proposed / planned'];
const colors={'Operational':'#087c88','Under construction':'#d7813e','Proposed / planned':'#7769a5'};
const bounds={west:-129,east:-62,south:14,north:58};
let records=[],selected=null,group=null,zoom=1,panX=0,panY=0,lastFocus=null,drag=null;
const filters={country:'All',stage:'All',type:'All',known:null,search:''};
const frame=$('#mapFrame'),world=$('#mapWorld'),pinLayer=$('#pinLayer');
function available(){return records.filter(r=>(filters.country==='All'||r.country===filters.country)&&(filters.stage==='All'||r.status===filters.stage)&&(filters.type==='All'||r.kind===filters.type)&&(filters.known===null||(r.capacity!==null)===filters.known)&&`${r.name} ${r.city} ${r.region} ${r.country} ${r.operator}`.toLowerCase().includes(filters.search));}
function xy(r){return{x:(r.lon-bounds.west)/(bounds.east-bounds.west)*frame.clientWidth,y:(bounds.north-r.lat)/(bounds.north-bounds.south)*frame.clientHeight};}
function clampPan(){const w=frame.clientWidth,h=frame.clientHeight;panX=Math.max(w*(1-zoom),Math.min(0,panX));panY=Math.max(h*(1-zoom),Math.min(0,panY));}
function applyTransform(){clampPan();world.style.transform=`translate(${panX}px,${panY}px) scale(${zoom})`;renderPins();}
function zoomAround(next,screenX=frame.clientWidth/2,screenY=frame.clientHeight/2){next=Math.max(1,Math.min(4,next));const ratio=next/zoom;panX=screenX-(screenX-panX)*ratio;panY=screenY-(screenY-panY)*ratio;zoom=next;applyTransform();}
function focusAt(point,next=Math.max(zoom,2)){zoom=Math.min(4,next);panX=frame.clientWidth/2-point.x*zoom;panY=frame.clientHeight/2-point.y*zoom;applyTransform();}
function showPinTip(button,text){const tip=$('#pinTooltip'),b=button.getBoundingClientRect(),f=frame.getBoundingClientRect();tip.textContent=text;tip.hidden=false;tip.style.left=`${Math.min(f.width-220,Math.max(8,b.left-f.left+18))}px`;tip.style.top=`${Math.max(8,b.top-f.top-48)}px`;}
function hidePinTip(){$('#pinTooltip').hidden=true;}
function renderPins(){if(!records.length)return;const rows=available(),w=frame.clientWidth,h=frame.clientHeight;pinLayer.replaceChildren();if(!w||!h)return;const clusters=[];for(const r of rows){const p=xy(r),sx=p.x*zoom+panX,sy=p.y*zoom+panY;let c=clusters.find(a=>Math.hypot(a.sx-sx,a.sy-sy)<31);if(c){c.rows.push(r);const n=c.rows.length;c.x=(c.x*(n-1)+p.x)/n;c.y=(c.y*(n-1)+p.y)/n;c.sx=c.x*zoom+panX;c.sy=c.y*zoom+panY;}else clusters.push({rows:[r],x:p.x,y:p.y,sx,sy});}
 for(const c of clusters){if(c.sx<-45||c.sx>w+45||c.sy<-45||c.sy>h+45)continue;const one=c.rows.length===1,r=c.rows[0],pin=document.createElement('button');pin.type='button';pin.className=`map-pin ${one?statusClass(r.status)+(r.kind==='Market'?' market':''):'cluster'} ${c.rows.some(x=>x.id===selected?.id)?'selected':''}`;pin.style.left=`${100*c.x/w}%`;pin.style.top=`${100*c.y/h}%`;pin.style.transform=`translate(-50%,-50%) scale(${1/zoom})`;if(!one)pin.textContent=String(c.rows.length);const title=one?`${r.name} — ${fmt(r.capacity)}; ${place(r)}`:`${c.rows.length} nearby entries — select to zoom and browse`;pin.setAttribute('aria-label',title);pin.title=title;pin.addEventListener('pointerenter',()=>showPinTip(pin,title));pin.addEventListener('pointerleave',hidePinTip);pin.addEventListener('focus',()=>showPinTip(pin,title));pin.addEventListener('blur',hidePinTip);pin.addEventListener('click',e=>{e.stopPropagation();hidePinTip();if(one){selectRecord(r);}else{group=c.rows;renderInspector();if(zoom<3.9)focusAt({x:c.x,y:c.y},Math.min(4,zoom*2));}});pinLayer.appendChild(pin);}}
function renderInspector(){const target=$('#inspectorContent');if(group){$('#selectionCount').textContent=`${group.length} NEARBY`;const first=group[0];target.innerHTML=`<h3>${group.length} locations nearby</h3><p class="inspector-place">Around ${esc(first.city)}, ${esc(first.region)}</p><p>Choose an entry to see its reported capacity and source.</p><div class="group-list">${group.map(r=>`<button type="button" data-id="${r.id}"><strong>${esc(r.name)}</strong><span>${statusLabel(r.status)} · ${fmt(r.capacity)}</span></button>`).join('')}</div>`;target.querySelectorAll('[data-id]').forEach(b=>b.addEventListener('click',()=>selectRecord(records.find(r=>r.id===b.dataset.id))));return;}
 if(!selected){$('#selectionCount').textContent='—';target.innerHTML='<h3>No locations shown</h3><p>Try changing the filters or search.</p>';return;}
 const i=records.findIndex(r=>r.id===selected.id)+1,r=selected;$('#selectionCount').textContent=`${String(i).padStart(2,'0')} / ${records.length}`;const source=r.sourceUrl?`<a href="${esc(r.sourceUrl)}" target="_blank" rel="noopener noreferrer">Open ${esc(r.sourceTitle)} ↗</a>`:'<a href="./sources.md" target="_blank" rel="noopener noreferrer">View compiled source notes ↗</a>';target.innerHTML=`<h3>${esc(r.name)}</h3><p class="inspector-place">${esc(place(r))}</p><div class="inspector-status"><i class="dot ${statusClass(r.status)}"></i>${statusLabel(r.status)} · ${r.kind}</div><div class="capacity-box"><small>CAPACITY / BASIS</small><strong>${fmt(r.capacity)}</strong><span>${esc(r.basis)}</span></div>${r.qualification?`<p>${esc(r.qualification)}</p>`:''}<p>${esc(r.notes)}</p><span class="verification">${esc(r.sourceQuality)}</span><br>${source}`;}
function selectRecord(r,focus=false){if(!r)return;selected=r;group=null;renderInspector();renderPins();if(focus)focusAt(xy(r),Math.max(zoom,2.2));}
function renderTable(){const rows=available();$('#visibleCount').textContent=`(${rows.length})`;$('#entries').innerHTML=rows.length?rows.map(r=>`<tr tabindex="0" data-id="${r.id}" aria-label="Show ${esc(r.name)} on map"><td>${esc(r.name)}${r.kind==='Market'?' · Market':''}</td><td>${esc(place(r))}</td><td><span class="stage-pill"><i class="dot ${statusClass(r.status)}"></i>${statusLabel(r.status)}</span></td><td>${fmt(r.capacity)}<small>${esc(r.basis)}</small></td><td>↗</td></tr>`).join(''):'<tr><td colspan="5">No entries match these filters.</td></tr>';$('#entries').querySelectorAll('[data-id]').forEach(row=>{const act=()=>{selectRecord(records.find(r=>r.id===row.dataset.id),true);frame.scrollIntoView({block:'center',behavior:'smooth'});};row.addEventListener('click',act);row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();act();}});});const note=[];if(filters.country!=='All')note.push(countries.find(c=>c[0]===filters.country)?.[1]);if(filters.stage!=='All')note.push(statusLabel(filters.stage));if(filters.known!==null)note.push(filters.known?'numeric MW':'unknown MW');if(filters.type!=='All')note.push(filters.type);$('#filterNote').textContent=note.join(' · ');$('#filterNote').hidden=!note.length;$('#clearFilters').hidden=!note.length&&!filters.search;}
function sync(){const rows=available();if(selected&&!rows.some(r=>r.id===selected.id)){selected=rows[0]||null;group=null;}if(group&&!group.some(r=>rows.some(x=>x.id===r.id)))group=null;renderTable();renderInspector();renderPins();renderCharts();$('#country').value=filters.country;$('#stageControls').querySelectorAll('button').forEach(b=>(b.classList.toggle('active',b.dataset.stage===filters.stage),b.setAttribute('aria-pressed',String(b.dataset.stage===filters.stage))));$('#typeControls').querySelectorAll('button').forEach(b=>(b.classList.toggle('active',b.dataset.type===filters.type),b.setAttribute('aria-pressed',String(b.dataset.type===filters.type))));}
function tooltip(el,html,event){const t=$('#chartTooltip');t.innerHTML=html;t.hidden=false;const b=el.getBoundingClientRect(),x=event?.clientX??b.left+b.width/2,y=event?.clientY??b.top;t.style.left=`${Math.min(innerWidth-t.offsetWidth-10,Math.max(10,x+12))}px`;t.style.top=`${Math.min(innerHeight-t.offsetHeight-10,Math.max(10,y+12))}px`;}
function bindChart(node){node.querySelectorAll('.bar-hit').forEach(el=>{const show=e=>tooltip(el,el.dataset.tip,e);el.addEventListener('pointerenter',show);el.addEventListener('pointermove',show);el.addEventListener('pointerleave',()=>$('#chartTooltip').hidden=true);el.addEventListener('focus',show);el.addEventListener('blur',()=>$('#chartTooltip').hidden=true);el.addEventListener('click',()=>{if(el.dataset.chart==='stage'){const same=filters.country===el.dataset.country&&filters.stage===el.dataset.stage;filters.country=same?'All':el.dataset.country;filters.stage=same?'All':el.dataset.stage;filters.known=null;}else{const known=el.dataset.known==='true',same=filters.stage===el.dataset.stage&&filters.known===known;filters.stage=same?'All':el.dataset.stage;filters.known=same?null:known;}$('#chartTooltip').hidden=true;sync();});el.addEventListener('keydown',e=>{if(el.tagName.toLowerCase()!=='button'&&(e.key==='Enter'||e.key===' ')){e.preventDefault();el.click();}});});}
function renderStageChart(){const x0=118,bw=312,ys=[30,80,130],p=[];for(let t=0;t<=30;t+=10){const x=x0+t/33*bw;p.push(`<line class="grid" x1="${x}" y1="17" x2="${x}" y2="164"/><text class="axis" x="${x}" y="178" text-anchor="middle">${t}</text>`);}countries.forEach(([country,label],i)=>{const subset=records.filter(r=>r.country===country),y=ys[i];p.push(`<text x="5" y="${y+17}" font-weight="700">${label}</text><text class="axis" x="465" y="${y+17}" text-anchor="end">n=${subset.length}</text>`);let x=x0;for(const stage of stages){const count=subset.filter(r=>r.status===stage).length,w=count/33*bw;if(!count)continue;const dim=(filters.country!=='All'&&filters.country!==country)||(filters.stage!=='All'&&filters.stage!==stage);const tip=`<b>${label} · ${statusLabel(stage)}</b><br>${count} of ${subset.length} entries <span>(${Math.round(100*count/subset.length)}%)</span><br><span>Click to filter</span>`;p.push(`<rect class="bar-hit ${dim?'dimmed':''}" x="${x}" y="${y}" width="${w}" height="26" rx="3" fill="${colors[stage]}" tabindex="0" role="button" aria-label="${label}: ${count} ${statusLabel(stage).toLowerCase()} entries" data-chart="stage" data-country="${country}" data-stage="${stage}" data-tip="${esc(tip)}"><title>${label}: ${count} ${statusLabel(stage).toLowerCase()}</title></rect>`);x+=w;}});const n=$('#stageChart');n.innerHTML=`<svg viewBox="0 0 470 185" role="group" aria-label="Counts of development stage by country">${p.join('')}</svg>`;n.insertAdjacentHTML("beforeend",mobileChartRows(n.id));bindChart(n);}
function renderDisclosureChart(){const x0=130,bw=290,ys=[30,80,130],p=[];stages.forEach((stage,i)=>{const subset=records.filter(r=>r.status===stage),known=subset.filter(r=>r.capacity!==null).length,y=ys[i];p.push(`<text x="5" y="${y+17}" font-weight="700">${statusLabel(stage)}</text><text class="axis" x="465" y="${y+17}" text-anchor="end">n=${subset.length}</text>`);let x=x0;for(const [isKnown,count,color] of [[true,known,'#087c88'],[false,subset.length-known,'#aebdc0']]){const w=count/subset.length*bw,dim=(filters.stage!=='All'&&filters.stage!==stage)||(filters.known!==null&&filters.known!==isKnown),label=isKnown?'numeric MW':'unknown MW',tip=`<b>${statusLabel(stage)} · ${label}</b><br>${count} of ${subset.length} entries <span>(${Math.round(100*count/subset.length)}%)</span><br><span>Click to filter</span>`;p.push(`<rect class="bar-hit ${dim?'dimmed':''}" x="${x}" y="${y}" width="${w}" height="26" rx="3" fill="${color}" tabindex="0" role="button" aria-label="${statusLabel(stage)}: ${count} entries with ${label}" data-chart="disclosure" data-stage="${stage}" data-known="${isKnown}" data-tip="${esc(tip)}"><title>${count} entries with ${label}</title></rect>`);x+=w;}p.push(`<text x="${x0+bw/2}" y="${y+18}" text-anchor="middle" pointer-events="none" font-size="11" font-weight="700">${Math.round(100*known/subset.length)}% numeric</text>`);});const n=$('#disclosureChart');n.innerHTML=`<svg viewBox="0 0 470 175" role="group" aria-label="Share of entries with numeric and unknown MW by stage">${p.join('')}</svg>`;n.insertAdjacentHTML("beforeend",mobileChartRows(n.id));bindChart(n);}
function mobileChartRows(id){const rows=id==='stageChart'?countries.map(([country,label])=>({label,rows:records.filter(r=>r.country===country),country})):stages.map(stage=>({label:statusLabel(stage),rows:records.filter(r=>r.status===stage),stage}));return `<div class="mobile-chart">${rows.map(group=>{const parts=id==='stageChart'?stages.map(stage=>({label:statusLabel(stage),count:group.rows.filter(r=>r.status===stage).length,stage,css:statusClass(stage)})):[true,false].map(known=>({label:known?'Numeric MW':'Unknown',count:group.rows.filter(r=>(r.capacity!==null)===known).length,known,css:known?'operating':'unknown'}));return `<div class="mobile-chart-row"><div class="mobile-row-label"><strong>${group.label}</strong><span>${group.rows.length} entries</span></div><div class="mobile-segments">${parts.map(part=>`<button type="button" class="bar-hit mobile-segment ${part.css}" data-chart="${id==='stageChart'?'stage':'disclosure'}" data-country="${group.country||''}" data-stage="${part.stage||group.stage}" data-known="${part.known}" data-tip="${esc(`<b>${group.label} · ${part.label}</b><br>${part.count} of ${group.rows.length} entries<br>Tap to filter`)}" aria-label="Filter ${group.label}, ${part.label}: ${part.count} entries"><span>${part.label}</span><strong>${part.count}</strong></button>`).join('')}</div></div>`;}).join('')}</div>`;}
function renderCharts(){renderStageChart();renderDisclosureChart();}
$('#zoomIn').addEventListener('click',()=>zoomAround(zoom*1.6));$('#zoomOut').addEventListener('click',()=>zoomAround(zoom/1.6));$('#resetMap').addEventListener('click',()=>{zoom=1;panX=panY=0;applyTransform();});frame.addEventListener('wheel',e=>{e.preventDefault();const b=frame.getBoundingClientRect();zoomAround(zoom*(e.deltaY<0?1.25:.8),e.clientX-b.left,e.clientY-b.top);},{passive:false});frame.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY};frame.setPointerCapture(e.pointerId);frame.classList.add('dragging');});frame.addEventListener('pointermove',e=>{if(!drag)return;panX+=e.clientX-drag.x;panY+=e.clientY-drag.y;drag={x:e.clientX,y:e.clientY};applyTransform();});function stopDrag(){drag=null;frame.classList.remove('dragging');}frame.addEventListener('pointerup',stopDrag);frame.addEventListener('pointercancel',stopDrag);new ResizeObserver(()=>applyTransform()).observe(frame);
$('#search').addEventListener('input',e=>{filters.search=e.target.value.trim().toLowerCase();sync();});$('#country').addEventListener('change',e=>{filters.country=e.target.value;sync();});$('#stageControls').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;filters.stage=b.dataset.stage;filters.known=null;sync();});$('#typeControls').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;filters.type=b.dataset.type;sync();});$('#clearFilters').addEventListener('click',()=>{filters.country='All';filters.stage='All';filters.type='All';filters.known=null;filters.search='';$('#search').value='';sync();});$('#methodButton').addEventListener('click',()=>{lastFocus=document.activeElement;$('#methodPanel').hidden=false;$('#overlay').hidden=false;$('#closeMethod').focus();});function closeMethod(){$('#methodPanel').hidden=true;$('#overlay').hidden=true;lastFocus?.focus?.();}$('#closeMethod').addEventListener('click',closeMethod);$('#overlay').addEventListener('click',closeMethod);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#methodPanel').hidden)closeMethod();});
fetch('./data.json').then(r=>{if(!r.ok)throw Error('Data unavailable');return r.json()}).then(rows=>{records=rows;selected=rows.find(r=>r.name.includes('Northern Virginia'))||rows[0];sync();}).catch(()=>{$('#entries').innerHTML='<tr><td colspan="5">Location data could not load. Please refresh.</td></tr>';$('#inspectorContent').innerHTML='<p>Location data unavailable.</p>';});

// Published context is independent of the curated register and map filters.
function bindContextChart(node){node.querySelectorAll('[data-context-tip]').forEach(el=>{const show=e=>tooltip(el,el.dataset.contextTip,e?.type==='focus'?null:e);el.addEventListener('pointerenter',show);el.addEventListener('pointermove',show);el.addEventListener('pointerleave',()=>$('#chartTooltip').hidden=true);el.addEventListener('focus',show);el.addEventListener('blur',()=>$('#chartTooltip').hidden=true);el.addEventListener('click',show);el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();show();}if(e.key==='Escape')$('#chartTooltip').hidden=true;});});}
function contextAttrs(label,tip){return `tabindex="0" role="button" aria-label="${esc(label)}" data-context-tip="${esc(tip)}"`;}
function renderCountryCapacity(data){const total=data.values.reduce((sum,r)=>sum+r.gw,0),radius=73,c=2*Math.PI*radius;let offset=0;const labels=[];const arcs=data.values.map((d,i)=>{const share=d.gw/total,len=share*c,label=`${d.country}: ${d.gw} GW, ${(share*100).toFixed(1)}%`,tip=`<b>${d.country}</b><br>${d.gw.toFixed(1)} GW live IT capacity<br>${(share*100).toFixed(1)}% of ${total.toFixed(1)} GW<br><span>RaboResearch · published March 2026</span>`;labels.push(`<button type="button" class="country-detail" ${contextAttrs(label,tip)}><i class="country-swatch country-${i}"></i><span><strong>${d.country}</strong><small>${d.gw.toFixed(1)} GW</small></span><b>${(share*100).toFixed(1)}%</b></button>`);const arc=`<circle class="context-mark country-${i}" cx="108" cy="108" r="${radius}" fill="none" stroke-width="29" stroke-dasharray="${len} ${c-len}" stroke-dashoffset="${-offset}" transform="rotate(-90 108 108)" ${contextAttrs(label,tip)}><title>${label}</title></circle>`;offset+=len;return arc;}).join('');$('#capacityChart').innerHTML=`<div class="capacity-layout"><svg viewBox="0 0 216 216" role="group" aria-label="Live IT capacity by country"><text x="108" y="106" text-anchor="middle" class="donut-total">${total.toFixed(1)}</text><text x="108" y="128" text-anchor="middle" class="axis">GW LIVE IT</text>${arcs}</svg><div class="country-details">${labels.join('')}</div></div>`;bindContextChart($('#capacityChart'));}
function renderSupplyGrowth(data){const width=Math.max(260,Math.min(480,$('#growthChart').clientWidth-32)),p=[],base=187,top=28,x0=40,step=(width-48)/5,barWidth=Math.min(54,step-14),max=10;for(let v=0;v<=10;v+=2){const y=base-v/max*(base-top);p.push(`<line class="grid" x1="37" x2="${width-5}" y1="${y}" y2="${y}"/><text class="axis" x="29" y="${y+4}" text-anchor="end">${v}</text>`);}p.push('<text class="axis" x="6" y="14">GW</text>');data.values.forEach((d,i)=>{const gw=d.mw/1000,h=gw/max*(base-top),x=x0+i*step,y=base-h,label=`${d.year}: ${d.mw.toLocaleString('en-US')} MW`,tip=`<b>Year-end ${d.year}</b><br>${d.mw.toLocaleString('en-US')} MW (${gw.toFixed(2)} GW)<br><span>CBRE U.S. primary markets, as reported<br>Coverage varies across annual reports</span>`;p.push(`<g class="context-mark growth-mark" ${contextAttrs(label,tip)}><rect x="${x-6}" y="${top}" width="${step}" height="${base-top+25}" fill="transparent"/><rect class="growth-bar" x="${x}" y="${y}" width="${barWidth}" height="${h}" rx="4"/><text x="${x+barWidth/2}" y="${y-8}" text-anchor="middle">${gw.toFixed(2)}</text><text x="${x+barWidth/2}" y="211" text-anchor="middle" class="axis">${d.year}</text><title>${label}</title></g>`);});$('#growthChart').innerHTML=`<svg viewBox="0 0 ${width} 224" role="group" aria-label="Reported US primary-market capacity, five year-end snapshots, changing coverage">${p.join('')}</svg>`;$('#growthSources').innerHTML='Sources: '+data.values.map(d=>`<a href="${esc(d.source)}" target="_blank" rel="noopener">${d.year} ↗</a>`).join(' · ');bindContextChart($('#growthChart'));}
fetch('./market-context.json').then(r=>{if(!r.ok)throw Error('Context unavailable');return r.json();}).then(data=>{renderCountryCapacity(data.country);renderSupplyGrowth(data.growth);renderForecast(data.forecast);let previousWidth=$('#growthChart').clientWidth;new ResizeObserver(()=>{const width=$('#growthChart').clientWidth;if(width!==previousWidth){previousWidth=width;renderSupplyGrowth(data.growth);}}).observe($('#growthChart'));}).catch(()=>{for(const id of ['capacityChart','growthChart','forecastChart'])$('#'+id).innerHTML='<p>Chart data could not load. Please refresh.</p>';});
document.addEventListener('pointerdown',e=>{if(!e.target.closest('[data-context-tip]'))$('#chartTooltip').hidden=true;});

document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#chartTooltip').hidden=true;if(e.key!=='Tab'||$('#methodPanel').hidden)return;const items=[...$('#methodPanel').querySelectorAll('button,a[href]')],first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});

function renderForecast(data){const max=120;$('#forecastChart').innerHTML=`<div class="forecast-axis" aria-hidden="true"><span>120 GW</span><span>60 GW</span><span>0</span></div><div class="forecast-columns">${data.values.map(d=>{const label=`${d.year}: ${d.gw} GW projected facility capacity`,tip=`<b>${d.year} forecast · ${d.gw} GW</b><br>North America facility capacity<br><span>Rystad Energy · risk-adjusted projection<br>Includes traditional, AI/HPC and crypto<br>Different scope from the other capacity charts</span>`;return `<button type="button" class="forecast-column" ${contextAttrs(label,tip)}><span class="forecast-plot"><span class="forecast-bar" style="height:${d.gw/max*100}%"><strong>${d.gw}<small> GW</small></strong></span></span><span class="forecast-year">${d.year}<small>Projected</small></span></button>`;}).join('')}</div>`;bindContextChart($('#forecastChart'));}
